import {Vector3} from 'three';
import {validGroundProjection} from './animation-ground-ik.js';

export const groundPelvisDefaults=()=>({enabled:false,parameter:'',feet:[],dimension:3,direction:[0,-1,0],lift:.5,distance:1,offset:.02,maxSlope:60,mask:-1,maxDrop:.5,maxRise:.25,weight:1,smoothTime:0,maxGap:.25});
const fields=new Set(Object.keys(groundPelvisDefaults()));
export function validGroundPelvis(value,effectors,rootBehavior='fixed'){
 if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(key=>!fields.has(key)))return false;
 const p={...groundPelvisDefaults(),...value},ids=new Set((effectors||[]).map(e=>e?.id));
 return validGroundProjection({enabled:p.enabled,parameter:p.parameter,dimension:p.dimension,direction:p.direction,lift:p.lift,distance:p.distance,offset:p.offset,maxSlope:p.maxSlope,mask:p.mask})&&Array.isArray(p.feet)&&p.feet.length<=64&&new Set(p.feet).size===p.feet.length&&p.feet.every(id=>typeof id==='string'&&ids.has(id))&&(!p.enabled||p.feet.length>0&&rootBehavior==='fixed')&&[p.maxDrop,p.maxRise].every(v=>Number.isFinite(v)&&v>=0&&v<=10000)&&Number.isFinite(p.weight)&&p.weight>=0&&p.weight<=1&&Number.isFinite(p.smoothTime)&&p.smoothTime>=0&&p.smoothTime<=60&&Number.isFinite(p.maxGap)&&p.maxGap>0&&p.maxGap<=60;
}

// All supports sample the same incoming pose. Only the shared pelvis translates;
// the existing full-body constraints solve those goals afterwards, once.
export class GroundPelvisIK{
 constructor(owner){this.owner=owner;this.p={...groundPelvisDefaults(),...owner.p.groundPelvis};this.rows=owner.rows.filter(row=>this.p.feet.includes(row.settings.id));this.direction=new Vector3(...this.p.direction).normalize();this.up=this.direction.clone().negate();this.source=new Vector3();this.point=new Vector3();this.normal=new Vector3();this.delta=new Vector3();this.states=new WeakMap();this.query={start:[0,0,0],end:[0,0,0],dimension:this.p.dimension,mask:this.p.mask,includeTriggers:false,ignore:owner.owner.object.id};this.debug=owner.debug.groundPelvis={active:false,hits:0,queries:0,requested:0,offset:0,applied:0,clamped:false,blocked:false,feet:this.rows.map(row=>({id:row.settings.id,hit:false,reason:'inactive',actor:'',slope:0,position:[0,0,0]}))};}
 apply(pose,weight,frame){
  const owner=this.owner,p=this.p,d=this.debug,key=frame?.context??owner.owner,time=frame?.time??owner.owner.time??0,epoch=frame?.epoch??owner.owner.ikEpoch??0;d.active=weight>0&&p.weight>0&&(!p.parameter||owner.owner.parameters.get(p.parameter)===true);d.hits=0;d.requested=d.offset=d.applied=0;d.clamped=d.blocked=false;for(const foot of d.feet){foot.hit=false;foot.reason='inactive';foot.actor='';}
  if(!d.active){this.states.delete(key);return;}const query=owner.owner.groundQuery;if(typeof query!=='function')throw Error('골반 지면 보정에 충돌 질의 연결이 필요해요.');let minimum=Infinity,complete=true;
  for(let i=0;i<this.rows.length;i++){
   const row=this.rows[i],s=row.solver,foot=d.feet[i];if(!owner.active.includes(s)){complete=false;foot.reason='inactive-goal';continue;}
   this.source.copy(s.positions.at(-1)).applyMatrix4(s.world);this.point.copy(this.source).addScaledVector(this.up,p.lift).toArray(this.query.start);this.point.copy(this.source).addScaledVector(this.direction,p.distance).toArray(this.query.end);d.queries++;const hit=owner.owner.groundQuery(this.query);if(hit?.then)throw Error('골반 지면 보정에는 준비된 동기 물리 월드가 필요해요.');if(!hit?.hit){complete=false;foot.reason='miss';continue;}
   if(!Array.isArray(hit.position)||!Array.isArray(hit.normal)||hit.position.length!==3||hit.normal.length!==3||!hit.position.every(Number.isFinite)||!hit.normal.every(Number.isFinite))throw Error('골반 지면 충돌 결과를 확인하세요.');this.normal.fromArray(hit.normal);if(this.normal.lengthSq()<1e-16){complete=false;foot.reason='normal';continue;}this.normal.normalize();foot.slope=Math.acos(Math.max(-1,Math.min(1,this.normal.dot(this.up))))*180/Math.PI;if(foot.slope>p.maxSlope+1e-7){complete=false;foot.reason='slope';continue;}
   this.point.fromArray(hit.position).addScaledVector(this.normal,p.offset);if(p.dimension===2)this.point.z=this.source.z;this.point.toArray(foot.position);const strength=(row.override.weight??row.settings.weight)*p.weight;minimum=Math.min(minimum,this.delta.copy(this.point).sub(this.source).dot(this.up)*strength);this.point.applyMatrix4(s.inverseWorld);s.target.lerpVectors(s.positions.at(-1),this.point,strength);s.target.toArray(owner.debug.effectors[owner.rows.indexOf(row)].target);foot.hit=true;foot.reason='';foot.actor=hit.actor||'';d.hits++;
  }
  if(!d.hits){this.states.delete(key);return;}if(!complete)minimum=Math.min(0,minimum);d.requested=minimum;let offset=Math.max(-p.maxDrop,Math.min(p.maxRise,minimum));d.clamped=offset!==minimum;const previous=this.states.get(key),dt=time-(previous?.time??time),continuous=previous&&previous.epoch===epoch-1&&dt>=0&&dt<=p.maxGap;
  if(p.smoothTime>0&&continuous)offset=previous.offset+(offset-previous.offset)*(-Math.expm1(-dt/p.smoothTime));
  d.blocked=owner.excluded.has(owner.root.name)||owner.rootStiffness===1;if(d.blocked)offset=0;this.states.set(key,{time,epoch,offset});if(!d.blocked)offset*=1-owner.rootStiffness;d.offset=offset;d.applied=offset*weight;
  if(!offset)return;const first=owner.chains[0];first.readPose(pose);first.chain[0].getWorldPosition(this.point);this.point.applyMatrix4(first.world).addScaledVector(this.up,offset).applyMatrix4(first.inverseWorld);first.chain[0].parent.worldToLocal(this.point);this.point.toArray(pose[owner.rootPosition]);
 }
 clear(){this.states=new WeakMap();}
}

export const groundPelvisContract={node:'fullBodyIK',property:'optional groundPelvis; disabled/absent adds no owner/query/history',fields:groundPelvisDefaults(),support:'Explicit unique effector IDs; same incoming pose, one existing ready Rapier ray per active positive-weight support. Foot targets use support weight * pelvis weight once. Missing/steep support cannot raise pelvis; no hits passes original targets/root.',root:'rootBehavior fixed required; smallest signed world-up support displacement, maxDrop/maxRise world meters, root positionStiffness/exclusion and final graph alpha retained. Translation only; original CCD/joint/orientation/stretch solve follows. No actor or root-motion extraction mutation.',history:'Optional exponential smoothTime in graph seconds; private branch WeakMap, epoch/gap/backwards clock/zero alpha/disabled/no support/disposal reset; each evaluation starts from incoming pose, never accumulated skeleton output.',authoring:'Typed per-effector toggles, bounds, smoothing/Bool parameter and existing graph Undo/CAS/save/runtime native Bool/Float parameter replay; removed/renamed goal references maintained.',limits:'Kinematic support/pelvis correction; not predicted gait, contacts/forces, arbitrary rig calibration, per-foot automatic phase, active rigid reaction or coupled root free/prePull optimization. No visual/device/whole-scene cost guarantee.'};
